import React from 'react';

const Home = () => (
  <div className="card" style={{ maxWidth: 600, margin: '40px auto', padding: 24 }}>
    <h1>Welcome to the Chaotic E-commerce Site</h1>
    <p>This is a demo e-commerce site with products, orders, notifications, analytics, and more. Use the navigation bar to explore the features.</p>
  </div>
);

export default Home;
